Definition A_R90_JT1 : Z := 0x3c618.
Definition A_R90_JTM : Z := 0x3c598.
Lemma rot90_jt : forall (m : mem), mem_inv asegs m ->
  ro_cells asegs m A_R90_JT1 [CB 4 [Z_to_bv 8 124; Z_to_bv 8 124; Z_to_bv 8 16; Z_to_bv 8 0]]
  /\ ro_cells asegs m A_R90_JTM [CB 4 [Z_to_bv 8 132; Z_to_bv 8 127; Z_to_bv 8 16; Z_to_bv 8 0]].
Proof.
  intros m MI. split;
  lazymatch goal with |- ro_cells _ _ ?A [CB _ ?bs] => change (ro_cells asegs m A [CB (length bs) bs]) end; (apply (Image.ro_cells_image asegs); [exact MI | vm_compute; reflexivity | unfold A_R90_JT1, A_R90_JTM; lia | cbn; unfold A_R90_JT1, A_R90_JTM; lia]).
Qed.

